import{_ as n,o as t,c as a,a2 as i}from"./chunks/framework.vLhlLNVn.js";const r="/assets/einrichten.c2w8hXiC.png",p=JSON.parse('{"title":"Installation und Voraussetzungen","description":"","frontmatter":{"order":1,"adapter":"sourceanalytix","editLink":"https://github.com/DrozmotiX/ioBroker.sourceanalytix/edit/main/docs/de/01.erste-schritte/01.installation.md"},"headers":[],"relativePath":"de/adapter/sourceanalytix/erste-schritte/installation.md","filePath":"de/adapter/sourceanalytix/erste-schritte/installation.md","lastUpdated":null}'),s={name:"de/adapter/sourceanalytix/erste-schritte/installation.md"};function l(o,e,d,u,c,h){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="installation-und-voraussetzungen" tabindex="-1">Installation und Voraussetzungen <a class="header-anchor" href="#installation-und-voraussetzungen" aria-label="Permalink to &quot;Installation und Voraussetzungen&quot;">​</a></h1><p><a id="requirements-sourceanalytix-have-node-js"></a></p><h2 id="welche-voraussetzungen-braucht-sourceanalytix-node-js-js-controller-admin" tabindex="-1">Welche Voraussetzungen braucht SourceAnalytix (Node.js, js-controller, Admin)? <a class="header-anchor" href="#welche-voraussetzungen-braucht-sourceanalytix-node-js-js-controller-admin" aria-label="Permalink to &quot;Welche Voraussetzungen braucht SourceAnalytix (Node.js, js-controller, Admin)?&quot;">​</a></h2><p>Du brauchst Node.js 22, js-controller 6.0.11 und Admin 8.0.0 oder neuer. Admin 8 ist nötig, weil die Einstellungsseite der Instanz aus Bausteinen von Admin 8 besteht.</p><p>Deine Versionen zeigt die Konsole mit <code>iobroker -v</code> (js-controller) und <code>node -v</code> (Node.js). Ist eine Komponente zu alt, aktualisiere zuerst sie und danach SourceAnalytix.</p><h3 id="sourceanalytix-startet-nach-einem-update-von-node-js-nicht" tabindex="-1">SourceAnalytix startet nach einem Update von Node.js nicht <a class="header-anchor" href="#sourceanalytix-startet-nach-einem-update-von-node-js-nicht" aria-label="Permalink to &quot;SourceAnalytix startet nach einem Update von Node.js nicht&quot;">​</a></h3><p>Meldet das Log <code>TypeError: Class extends value … is not a constructor or null</code>, ist meist der js-controller zu alt. Aktualisiere ihn, führe <code>iob fix</code> aus und starte die Instanz neu. In Docker aktualisierst du stattdessen das Container-Image.</p><p><strong>Siehe auch:</strong> <a href="./../anleitungen/betrieb-und-wartung#update-sourceanalytix-downgrade">Wie aktualisiere ich SourceAnalytix?</a> · <a href="./../fehlerbehebung/log-meldungen#installation-admin-display-problems">Probleme bei Installation und Admin-Anzeige</a></p><p><a id="install-sourceanalytix-create-instance"></a></p><h2 id="wie-installiere-ich-sourceanalytix-und-lege-eine-instanz-an" tabindex="-1">Wie installiere ich SourceAnalytix und lege eine Instanz an? <a class="header-anchor" href="#wie-installiere-ich-sourceanalytix-und-lege-eine-instanz-an" aria-label="Permalink to &quot;Wie installiere ich SourceAnalytix und lege eine Instanz an?&quot;">​</a></h2><p>SourceAnalytix steht im Repository „latest“ (Beta), noch nicht in „stable“. Stelle „latest“ ein, installiere den Adapter und richte dann in den Instanz-Einstellungen deine erste Quelle ein.</p><ol><li>Wähle in Admin unter Systemeinstellungen › „Repositories“ das Repository „latest“.</li><li>Suche im Reiter „Adapter“ nach „SourceAnalytix“ und installiere es. Admin legt die Instanz <code>sourceanalytix.0</code> an und startet sie.</li><li>Öffne im Reiter „Instanzen“ die Einstellungen von <code>sourceanalytix.0</code>.</li><li>Lege im Tab „Preisdefinitionen“ mindestens einen Preis an, zum Beispiel für Strom in kWh, und speichere.</li><li>Klicke im Tab „Übersicht“ auf „Erste Quelle hinzufügen“. Weiter geht es unter <a href="./erster-zaehler#configure-sourceanalytix-datapoint">Mein erster Zähler</a>.</li></ol><p><img src="'+r+'" alt="Tab „Übersicht“ direkt nach der Installation mit der Karte „SourceAnalytix einrichten“"></p><p>Die Tabs „Übersicht“ und „Probleme“ brauchen eine laufende Instanz. Ist sie gestoppt, steht oben „Instanz läuft nicht“ mit dem Knopf „Starten“.</p><h3 id="es-gibt-keine-instanz" tabindex="-1">Es gibt keine Instanz <a class="header-anchor" href="#es-gibt-keine-instanz" aria-label="Permalink to &quot;Es gibt keine Instanz&quot;">​</a></h3><p>Nach einer Installation über die Konsole oder eine GitHub-Adresse fehlt die Instanz. Lege sie im Reiter „Adapter“ mit dem Plus-Symbol an. Eine GitHub-Installation ist nur zum Testen gedacht, Admin zeigt dafür keine Updates an.</p><p><strong>Siehe auch:</strong> <a href="#need-several-instances-versions-side">Brauche ich mehrere Instanzen?</a></p><p><a id="need-several-instances-versions-side"></a></p><h2 id="brauche-ich-mehrere-instanzen-oder-versionen-nebeneinander" tabindex="-1">Brauche ich mehrere Instanzen oder Versionen nebeneinander? <a class="header-anchor" href="#brauche-ich-mehrere-instanzen-oder-versionen-nebeneinander" aria-label="Permalink to &quot;Brauche ich mehrere Instanzen oder Versionen nebeneinander?&quot;">​</a></h2><p>Nein. Eine Instanz verarbeitet beliebig viele Quellen. Zwei Versionen nebeneinander gibt es nicht, ioBroker installiert von jedem Adapter genau eine Version. Eine neue Version testest du deshalb nach einem Backup als Update.</p><h3 id="eine-uberzahlige-instanz-entfernen" tabindex="-1">Eine überzählige Instanz entfernen <a class="header-anchor" href="#eine-uberzahlige-instanz-entfernen" aria-label="Permalink to &quot;Eine überzählige Instanz entfernen&quot;">​</a></h3><ol><li>Prüfe im Reiter „Objekte“, unter welcher Instanz deine Werte liegen, also <code>sourceanalytix.0</code> oder <code>sourceanalytix.1</code>.</li><li>Lösche im Reiter „Instanzen“ die andere Instanz mit dem Papierkorb-Symbol.</li></ol><div class="caution custom-block github-alert"><p class="custom-block-title">CAUTION</p><p>Mit einer Instanz verschwinden auch alle ihre Werte. Willst du nur eine Quelle stilllegen, nimm bei der Quelle „Deaktivieren“.</p></div><p><strong>Siehe auch:</strong> <a href="./../anleitungen/betrieb-und-wartung#disable-datapoint-remove-sources-states">Datenpunkt deaktivieren oder Quelle entfernen</a></p>',24)])])}const b=n(s,[["render",l]]);export{p as __pageData,b as default};
